CREATE TABLE "announcements" ("id" integer primary key autoincrement not null, "title" varchar not null, "message" text not null, "audience" varchar check ("audience" in ('all', 'buyer', 'seller', 'courier')) not null default 'all', "active" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime);
CREATE TABLE "audit_logs" ("id" integer primary key autoincrement not null, "actor_id" integer, "actor_role" varchar, "action" varchar not null, "permission" varchar, "subject_type" varchar, "subject_id" integer, "changes" text, "metadata" text, "ip_address" varchar, "user_agent" varchar, "created_at" datetime not null default CURRENT_TIMESTAMP, "module" varchar, "result" varchar not null default 'success', foreign key("actor_id") references "users"("id") on delete set null);
CREATE TABLE "cache" ("key" varchar not null, "value" text not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE "cache_locks" ("key" varchar not null, "owner" varchar not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE "cart_items" ("id" integer primary key autoincrement not null, "cart_id" integer not null, "product_id" integer not null, "variation_id" integer, "quantity" integer not null default '1', "created_at" datetime, "updated_at" datetime, foreign key("cart_id") references "carts"("id") on delete cascade, foreign key("product_id") references "products"("id") on delete cascade, foreign key("variation_id") references "product_variations"("id") on delete set null);
CREATE TABLE "carts" ("id" integer primary key autoincrement not null, "buyer_id" integer not null, "created_at" datetime, "updated_at" datetime, foreign key("buyer_id") references "users"("id") on delete cascade);
CREATE TABLE "commission_rate_histories" ("id" integer primary key autoincrement not null, "rate" numeric not null, "changed_by" integer, "effective_from" datetime not null, "effective_until" datetime, "created_at" datetime, "updated_at" datetime, foreign key("changed_by") references "users"("id") on delete set null);
CREATE TABLE "complaints" ("id" integer primary key autoincrement not null, "filed_by" integer not null, "against_user_id" integer, "subject" varchar not null, "details" text not null, "evidence_path" varchar, "status" varchar not null default ('open'), "admin_notes" text, "created_at" datetime, "updated_at" datetime, "order_id" integer, "resolution_type" varchar, "resolution_notes" text, "resolved_at" datetime, foreign key("against_user_id") references users("id") on delete set null on update no action, foreign key("filed_by") references users("id") on delete cascade on update no action, foreign key("order_id") references "orders"("id") on delete set null);
CREATE TABLE "compliance_actions" ("id" integer primary key autoincrement not null, "seller_id" integer not null, "compliance_case_id" integer, "actor_id" integer not null, "action" varchar not null, "reason" text, "attachments" text, "metadata" text, "created_at" datetime, "updated_at" datetime, foreign key("seller_id") references "users"("id"), foreign key("compliance_case_id") references "compliance_cases"("id") on delete cascade, foreign key("actor_id") references "users"("id"));
CREATE TABLE "compliance_cases" ("id" integer primary key autoincrement not null, "seller_id" integer not null, "opened_by" integer not null, "product_id" integer, "type" varchar not null, "status" varchar not null default 'open', "severity" varchar not null default 'medium', "description" text not null, "resolved_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("seller_id") references "users"("id"), foreign key("opened_by") references "users"("id"), foreign key("product_id") references "products"("id") on delete set null);
CREATE TABLE "failed_jobs" ("id" integer primary key autoincrement not null, "uuid" varchar not null, "connection" varchar not null, "queue" varchar not null, "payload" text not null, "exception" text not null, "failed_at" datetime not null default CURRENT_TIMESTAMP);
CREATE TABLE "financial_ledger_entries" ("id" integer primary key autoincrement not null, "refund_id" integer, "order_id" integer not null, "entry_type" varchar not null, "account" varchar not null, "direction" varchar not null, "amount" numeric not null, "created_at" datetime not null default (CURRENT_TIMESTAMP), foreign key("order_id") references orders("id") on delete cascade on update no action, foreign key("refund_id") references refunds("id") on delete cascade on update no action);
CREATE TABLE "financial_transactions" ("id" integer primary key autoincrement not null, "order_id" integer, "seller_id" integer, "type" varchar not null, "debit" numeric not null default '0', "credit" numeric not null default '0', "amount" numeric not null, "reference_type" varchar, "reference_id" integer, "status" varchar not null default 'posted', "description" text, "created_by" integer, "created_at" datetime, "updated_at" datetime, foreign key("order_id") references "orders"("id") on delete set null, foreign key("seller_id") references "users"("id") on delete set null, foreign key("created_by") references "users"("id") on delete set null);
CREATE TABLE "geo_barangays" ("code" varchar not null, "municipality_code" varchar not null, "name" varchar not null, primary key ("code"));
CREATE TABLE "geo_municipalities" ("code" varchar not null, "province_code" varchar not null, "region_code" varchar not null, "name" varchar not null, "is_city" tinyint(1) not null default '0', "is_capital" tinyint(1) not null default '0', primary key ("code"));
CREATE TABLE "geo_provinces" ("code" varchar not null, "region_code" varchar not null, "name" varchar not null, "kind" varchar check ("kind" in ('province', 'district')) not null default 'province', primary key ("code"));
CREATE TABLE "geo_regions" ("code" varchar not null, "name" varchar not null, "region_name" varchar, primary key ("code"));
CREATE TABLE "job_batches" ("id" varchar not null, "name" varchar not null, "total_jobs" integer not null, "pending_jobs" integer not null, "failed_jobs" integer not null, "failed_job_ids" text not null, "options" text, "cancelled_at" integer, "created_at" integer not null, "finished_at" integer, primary key ("id"));
CREATE TABLE "jobs" ("id" integer primary key autoincrement not null, "queue" varchar not null, "payload" text not null, "attempts" integer not null, "reserved_at" integer, "available_at" integer not null, "created_at" integer not null);
CREATE TABLE "messages" ("id" integer primary key autoincrement not null, "sender_id" integer not null, "receiver_id" integer not null, "body" text not null, "read" tinyint(1) not null default ('0'), "created_at" datetime, "updated_at" datetime, "product_id" integer, foreign key("receiver_id") references users("id") on delete cascade on update no action, foreign key("sender_id") references users("id") on delete cascade on update no action, foreign key("product_id") references "products"("id") on delete set null);
CREATE TABLE "migrations" ("id" integer primary key autoincrement not null, "migration" varchar not null, "batch" integer not null);
CREATE TABLE "notifications" ("id" varchar not null, "type" varchar not null, "notifiable_type" varchar not null, "notifiable_id" integer not null, "data" text not null, "read_at" datetime, "created_at" datetime, "updated_at" datetime, primary key ("id"));
CREATE TABLE "order_status_histories" ("id" integer primary key autoincrement not null, "order_id" integer not null, "changed_by" integer, "source" varchar not null, "from_status" varchar, "to_status" varchar not null, "reason" text, "created_at" datetime, "updated_at" datetime, foreign key("order_id") references "orders"("id") on delete cascade, foreign key("changed_by") references "users"("id") on delete set null);
CREATE TABLE "orders" ("id" integer primary key autoincrement not null, "order_number" varchar not null, "buyer_id" integer not null, "seller_id" integer not null, "product_name" varchar not null, "amount" numeric not null, "commission" numeric not null, "status" varchar not null default ('placed'), "created_at" datetime, "updated_at" datetime, "product_id" integer, "quantity" integer not null default ('1'), "waybill_number" varchar, "tracking_status" varchar, "packed_at" datetime, "handed_over_at" datetime, "delivered_at" datetime, "rating" integer, "feedback" text, "confirmed_by_seller_at" datetime, "confirmed_at" datetime, "preparing_at" datetime, "ready_for_pickup_at" datetime, "picked_up_at" datetime, "sorting_received_at" datetime, "sorted_at" datetime, "assigned_to_rider_at" datetime, "out_for_delivery_at" datetime, "completed_at" datetime, "commission_rate" numeric, foreign key("product_id") references products("id") on delete set null on update no action, foreign key("buyer_id") references users("id") on delete cascade on update no action, foreign key("seller_id") references users("id") on delete cascade on update no action);
CREATE TABLE "password_reset_tokens" ("email" varchar not null, "token" varchar not null, "created_at" datetime, primary key ("email"));
CREATE TABLE "platform_settings" ("id" integer primary key autoincrement not null, "key" varchar not null, "value" text, "created_at" datetime, "updated_at" datetime);
CREATE TABLE "pr_assignments" ("id" integer primary key autoincrement not null, "parcel_id" integer not null, "rider_id" integer not null, "type" varchar check ("type" in ('pickup', 'delivery', 'return')) not null, "assigned_by" integer, "assigned_at" datetime not null, "status" varchar check ("status" in ('assigned', 'out_for_delivery', 'completed', 'failed', 'reassigned', 'cancelled')) not null default 'assigned', "attempt_no" integer not null default '1', "fail_reason" varchar, "fail_note" text, "proof_photo_path" varchar, "cod_collected" numeric, "cod_remittance_id" integer, "completed_at" datetime, "created_at" datetime, "updated_at" datetime, "batch_id" integer, "arrived_at" datetime, "arrival_lat" numeric, "arrival_lng" numeric, "arrival_distance_m" integer, "loaded_at" datetime, "returned_at" datetime, foreign key("parcel_id") references "pr_parcels"("id"), foreign key("rider_id") references "pr_riders"("id"), foreign key("assigned_by") references "pr_staff"("id") on delete set null);
CREATE TABLE "pr_audit_logs" ("id" integer primary key autoincrement not null, "actor_type" varchar not null, "actor_id" integer, "actor_hub_id" integer, "action" varchar not null, "subject_type" varchar, "subject_id" integer, "before" text, "after" text, "ip" varchar, "created_at" datetime not null default CURRENT_TIMESTAMP);
CREATE TABLE "pr_cod_remittances" ("id" integer primary key autoincrement not null, "rider_id" integer not null, "station_hub_id" integer not null, "remit_date" date not null, "expected_amount" numeric not null, "received_amount" numeric not null, "variance" numeric not null, "status" varchar check ("status" in ('reconciled', 'disputed')) not null, "received_by" integer not null, "second_counter_id" integer, "note" text, "resolved_by" integer, "resolved_at" datetime, "resolution_note" text, "hub_remittance_id" integer, "created_at" datetime, "updated_at" datetime, foreign key("rider_id") references "pr_riders"("id"), foreign key("station_hub_id") references "pr_hubs"("id"), foreign key("received_by") references "pr_staff"("id"), foreign key("second_counter_id") references "pr_staff"("id") on delete set null, foreign key("resolved_by") references "pr_staff"("id") on delete set null);
CREATE TABLE "pr_exceptions" ("id" integer primary key autoincrement not null, "hub_id" integer not null, "against_hub_id" integer, "parcel_id" integer, "manifest_id" integer, "type" varchar check ("type" in ('missing', 'damaged', 'mis_sorted', 'unlabeled', 'no_route')) not null, "note" text, "photo_path" varchar, "status" varchar check ("status" in ('open', 'resolved')) not null default 'open', "resolution" varchar, "resolution_note" text, "opened_by" integer, "resolved_by" integer, "resolved_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("hub_id") references "pr_hubs"("id"), foreign key("against_hub_id") references "pr_hubs"("id") on delete set null, foreign key("parcel_id") references "pr_parcels"("id"), foreign key("manifest_id") references "pr_manifests"("id") on delete set null, foreign key("opened_by") references "pr_staff"("id") on delete set null, foreign key("resolved_by") references "pr_staff"("id") on delete set null);
CREATE TABLE "pr_hub_remittances" ("id" integer primary key autoincrement not null, "station_hub_id" integer not null, "expected_amount" numeric not null, "remitted_amount" numeric not null, "variance" numeric not null, "reference_no" varchar, "status" varchar check ("status" in ('submitted', 'confirmed', 'disputed')) not null default 'submitted', "submitted_by" integer not null, "confirmed_by" integer, "confirmed_at" datetime, "note" text, "created_at" datetime, "updated_at" datetime, foreign key("station_hub_id") references "pr_hubs"("id"), foreign key("submitted_by") references "pr_staff"("id"), foreign key("confirmed_by") references "pr_staff"("id") on delete set null);
CREATE TABLE "pr_hubs" ("id" integer primary key autoincrement not null, "code" varchar not null, "name" varchar not null, "type" varchar check ("type" in ('province', 'station')) not null, "parent_hub_id" integer, "psgc_code" varchar not null, "region_code" varchar not null, "province_name" varchar not null, "municipality_name" varchar, "address" varchar, "lat" numeric, "lng" numeric, "is_active" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime, "address_city_code" varchar, "address_barangay_code" varchar, "address_line" varchar, foreign key("parent_hub_id") references "pr_hubs"("id") on delete set null);
CREATE TABLE "pr_manifest_parcels" ("id" integer primary key autoincrement not null, "manifest_id" integer not null, "parcel_id" integer not null, "scan_status" varchar check ("scan_status" in ('expected', 'scanned', 'missing', 'extra')) not null default 'expected', "scanned_at" datetime, foreign key("manifest_id") references "pr_manifests"("id") on delete cascade, foreign key("parcel_id") references "pr_parcels"("id"));
CREATE TABLE "pr_manifests" ("id" integer primary key autoincrement not null, "manifest_no" varchar not null, "from_hub_id" integer not null, "to_hub_id" integer not null, "status" varchar check ("status" in ('draft', 'dispatched', 'received', 'closed')) not null default 'draft', "vehicle_plate" varchar, "driver_name" varchar, "parcel_count" integer not null default '0', "created_by" integer not null, "dispatched_by" integer, "dispatched_at" datetime, "received_by" integer, "received_at" datetime, "closed_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("from_hub_id") references "pr_hubs"("id"), foreign key("to_hub_id") references "pr_hubs"("id"), foreign key("created_by") references "pr_staff"("id"), foreign key("dispatched_by") references "pr_staff"("id") on delete set null, foreign key("received_by") references "pr_staff"("id") on delete set null);
CREATE TABLE "pr_parcel_events" ("id" integer primary key autoincrement not null, "parcel_id" integer not null, "status" varchar not null, "hub_id" integer, "to_hub_id" integer, "rider_id" integer, "actor_type" varchar not null, "actor_id" integer, "note" text, "meta" text, "idempotency_key" varchar, "occurred_at" datetime not null, "created_at" datetime not null default CURRENT_TIMESTAMP, foreign key("parcel_id") references "pr_parcels"("id") on delete cascade, foreign key("hub_id") references "pr_hubs"("id") on delete set null, foreign key("to_hub_id") references "pr_hubs"("id") on delete set null);
CREATE TABLE "pr_parcels" ("id" integer primary key autoincrement not null, "tracking_no" varchar not null, "source" varchar not null default ('picksell'), "external_ref" varchar, "origin_hub_id" integer, "dest_hub_id" integer, "current_hub_id" integer, "next_hub_id" integer, "current_status" varchar, "shipper_name" varchar not null, "shipper_mobile" varchar, "pickup_address" varchar, "pickup_barangay_code" varchar, "pickup_municipality_code" varchar, "consignee_name" varchar not null, "consignee_mobile" varchar, "delivery_address" varchar, "delivery_barangay_code" varchar, "delivery_municipality_code" varchar, "item_description" varchar, "weight_kg" numeric, "size_category" varchar, "cod_amount" numeric not null default ('0'), "shipping_fee" numeric not null default ('0'), "attempt_count" integer not null default ('0'), "is_return" tinyint(1) not null default ('0'), "needs_address_fix" tinyint(1) not null default ('0'), "delivered_at" datetime, "created_at" datetime, "updated_at" datetime, "sorted_at" datetime, "sorted_by" integer, "pickup_lat" numeric, "pickup_lng" numeric, foreign key("next_hub_id") references pr_hubs("id") on delete set null on update no action, foreign key("current_hub_id") references pr_hubs("id") on delete set null on update no action, foreign key("dest_hub_id") references pr_hubs("id") on delete set null on update no action, foreign key("origin_hub_id") references pr_hubs("id") on delete set null on update no action, foreign key("sorted_by") references "pr_staff"("id") on delete set null);
CREATE TABLE "pr_rider_batches" ("id" integer primary key autoincrement not null, "batch_no" varchar, "type" varchar not null default 'pickup', "rider_id" integer not null, "station_hub_id" integer not null, "status" varchar not null default ('offered'), "assigned_by" integer, "offered_at" datetime not null, "responded_at" datetime, "decline_reason" varchar, "completed_at" datetime, "created_at" datetime, "updated_at" datetime, "hub_arrived_at" datetime, "hub_arrival_lat" numeric, "hub_arrival_lng" numeric, "hub_arrival_distance_m" integer, "started_at" datetime, foreign key("assigned_by") references pr_staff("id") on delete set null on update no action, foreign key("station_hub_id") references pr_hubs("id") on delete no action on update no action, foreign key("rider_id") references pr_riders("id") on delete no action on update no action);
CREATE TABLE "pr_rider_documents" ("id" integer primary key autoincrement not null, "rider_id" integer not null, "doc_type" varchar not null, "file_path" varchar not null, "expiry_date" date, "uploaded_by" integer, "created_at" datetime, "updated_at" datetime, "side" varchar, foreign key("uploaded_by") references pr_staff("id") on delete no action on update no action, foreign key("rider_id") references pr_riders("id") on delete cascade on update no action);
CREATE TABLE "pr_rider_email_codes" ("id" integer primary key autoincrement not null, "email" varchar not null, "code_hash" varchar not null, "attempts" integer not null default '0', "expires_at" datetime not null, "verified_at" datetime, "token_hash" varchar, "created_at" datetime, "updated_at" datetime);
CREATE TABLE "pr_rider_notifications" ("id" integer primary key autoincrement not null, "rider_id" integer not null, "type" varchar not null, "title" varchar not null, "body" varchar, "data" text, "read_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("rider_id") references "pr_riders"("id") on delete cascade);
CREATE TABLE "pr_rider_reports" ("id" integer primary key autoincrement not null, "rider_id" integer not null, "station_hub_id" integer not null, "batch_id" integer, "type" varchar not null, "note" text, "lat" numeric, "lng" numeric, "resolved_by" integer, "resolved_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("rider_id") references "pr_riders"("id"), foreign key("station_hub_id") references "pr_hubs"("id"), foreign key("resolved_by") references "pr_staff"("id") on delete set null);
CREATE TABLE "pr_rider_tokens" ("id" integer primary key autoincrement not null, "rider_id" integer not null, "token_hash" varchar not null, "last_used_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("rider_id") references "pr_riders"("id") on delete cascade);
CREATE TABLE "pr_riders" ("id" integer primary key autoincrement not null, "station_hub_id" integer not null, "zone_id" integer, "full_name" varchar not null, "mobile_no" varchar not null, "birthdate" date, "address" varchar, "emergency_contact_name" varchar, "emergency_contact_no" varchar, "vehicle_type" varchar, "vehicle_model" varchar, "plate_no" varchar, "status" varchar not null default ('pending'), "shift_status" varchar not null default ('off_duty'), "cod_limit" numeric not null, "max_parcels" integer not null, "on_probation" tinyint(1) not null default ('1'), "device_id" varchar, "payout_method" varchar, "payout_account" varchar, "status_reason" text, "created_by" integer, "verified_by" integer, "verified_at" datetime, "approved_by" integer, "approved_at" datetime, "created_at" datetime, "updated_at" datetime, "first_name" varchar, "last_name" varchar, "email" varchar, "password" varchar, "province_code" varchar, "province_name" varchar, "city_code" varchar, "city_name" varchar, "barangay_code" varchar, "barangay_name" varchar, "street" varchar, "license_no" varchar, "applied_at" datetime, foreign key("approved_by") references pr_staff("id") on delete set null on update no action, foreign key("verified_by") references pr_staff("id") on delete set null on update no action, foreign key("created_by") references pr_staff("id") on delete no action on update no action, foreign key("station_hub_id") references pr_hubs("id") on delete no action on update no action);
CREATE TABLE "pr_settings" ("key" varchar not null, "value" text not null, "updated_by" integer, "updated_at" datetime, foreign key("updated_by") references "pr_staff"("id") on delete set null, primary key ("key"));
CREATE TABLE "pr_staff" ("id" integer primary key autoincrement not null, "full_name" varchar not null, "email" varchar not null, "mobile_no" varchar, "password" varchar not null, "role" varchar check ("role" in ('super_admin', 'finance', 'support', 'hub_manager', 'dispatcher', 'sorter')) not null, "hub_id" integer, "is_active" tinyint(1) not null default '1', "is_sample" tinyint(1) not null default '0', "last_login_at" datetime, "remember_token" varchar, "created_at" datetime, "updated_at" datetime, foreign key("hub_id") references "pr_hubs"("id") on delete set null);
CREATE TABLE "pr_vehicles" ("id" integer primary key autoincrement not null, "hub_id" integer not null, "plate_no" varchar not null, "vehicle_type" varchar not null, "capacity_parcels" integer, "driver_name" varchar, "driver_mobile" varchar, "is_active" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime, foreign key("hub_id") references "pr_hubs"("id"));
CREATE TABLE "pr_zone_barangays" ("id" integer primary key autoincrement not null, "zone_id" integer not null, "barangay_code" varchar not null, foreign key("zone_id") references "pr_zones"("id") on delete cascade);
CREATE TABLE "pr_zones" ("id" integer primary key autoincrement not null, "station_hub_id" integer not null, "name" varchar not null, "default_rider_id" integer, "backup_rider_id" integer, "max_parcels" integer, "created_at" datetime, "updated_at" datetime, foreign key("station_hub_id") references "pr_hubs"("id") on delete cascade, foreign key("default_rider_id") references "pr_riders"("id") on delete set null, foreign key("backup_rider_id") references "pr_riders"("id") on delete set null);
CREATE TABLE "product_images" ("id" integer primary key autoincrement not null, "product_id" integer not null, "image_url" varchar not null, "display_order" integer not null default '1', "is_primary" tinyint(1) not null default '0', "alt_text" varchar, "created_at" datetime, "updated_at" datetime, foreign key("product_id") references "products"("id") on delete cascade);
CREATE TABLE "product_moderation_logs" ("id" integer primary key autoincrement not null, "product_id" integer not null, "admin_id" integer not null, "action" varchar not null, "from_status" varchar, "to_status" varchar, "reason" text, "created_at" datetime, "updated_at" datetime, foreign key("product_id") references "products"("id") on delete cascade, foreign key("admin_id") references "users"("id"));
CREATE TABLE "product_reviews" ("id" integer primary key autoincrement not null, "product_id" integer not null, "buyer_id" integer not null, "order_id" integer, "rating" integer not null, "body" text, "created_at" datetime, "updated_at" datetime, foreign key("product_id") references "products"("id") on delete cascade, foreign key("buyer_id") references "users"("id") on delete cascade, foreign key("order_id") references "orders"("id") on delete set null);
CREATE TABLE "product_variations" ("id" integer primary key autoincrement not null, "product_id" integer not null, "type" varchar not null, "value" varchar not null, "stock" integer not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("product_id") references "products"("id") on delete cascade);
CREATE TABLE "products" ("id" integer primary key autoincrement not null, "seller_id" integer not null, "name" varchar not null, "description" text, "category" varchar, "price" numeric not null, "discount" numeric not null default '0', "voucher_code" varchar, "voucher_discount" numeric not null default '0', "stock" integer not null default '0', "status" varchar check ("status" in ('active', 'archived')) not null default 'active', "created_at" datetime, "updated_at" datetime, "is_featured" tinyint(1) not null default '0', foreign key("seller_id") references "users"("id") on delete cascade);
CREATE TABLE "recently_viewed_products" ("id" integer primary key autoincrement not null, "user_id" integer not null, "product_id" integer not null, "viewed_at" datetime not null, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade, foreign key("product_id") references "products"("id") on delete cascade);
CREATE TABLE "refunds" ("id" integer primary key autoincrement not null, "order_id" integer not null, "return_request_id" integer, "requested_by" integer, "approved_by" integer, "amount" numeric not null, "commission_reversal" numeric not null default '0', "seller_adjustment" numeric not null default '0', "status" varchar not null default 'requested', "reason" text, "decision_notes" text, "approved_at" datetime, "processed_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("order_id") references "orders"("id") on delete cascade, foreign key("return_request_id") references "return_requests"("id") on delete set null, foreign key("requested_by") references "users"("id") on delete set null, foreign key("approved_by") references "users"("id") on delete set null);
CREATE TABLE "registration_reviews" ("id" integer primary key autoincrement not null, "user_id" integer not null, "reviewed_by" integer not null, "decision" varchar not null, "reason" text, "verification_snapshot" text, "reviewed_at" datetime not null, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade, foreign key("reviewed_by") references "users"("id"));
CREATE TABLE "return_request_events" ("id" integer primary key autoincrement not null, "return_request_id" integer not null, "actor_user_id" integer, "event_type" varchar not null, "from_status" varchar, "to_status" varchar not null, "notes" text, "metadata" text, "created_at" datetime, "updated_at" datetime, foreign key("return_request_id") references "return_requests"("id") on delete cascade, foreign key("actor_user_id") references "users"("id") on delete set null);
